import type { Metadata } from 'next'
import { getSeoSettings } from '@/lib/data/content'

const SITE_NAME = 'Bodo Desderio'
const SITE_URL = process.env.NEXT_PUBLIC_SITE_URL || 'https://bododesderio.com'
/** Generated by app/opengraph-image.tsx; used whenever a page has no image of its own. */
const DEFAULT_OG_IMAGE = { url: '/opengraph-image', width: 1200, height: 630 }

export interface PageSeo {
  /** Row in Settings > SEO; its title, description, image and canonical win over the defaults. */
  page?: string
  /** Full title as it should appear in search results. */
  title: string
  description: string
  path: string
  type?: 'website' | 'profile' | 'article'
  image?: string | null
  noindex?: boolean
  article?: { publishedTime?: string; modifiedTime?: string; tags?: string[] }
}

function absolute(url: string) {
  return /^https?:\/\//.test(url) ? url : `${SITE_URL}${url.startsWith('/') ? '' : '/'}${url}`
}

/**
 * One place for page metadata. A page-level `openGraph` replaces the root one
 * wholesale in Next, which silently dropped the share image on most pages, so
 * every page goes through here and always carries an image, URL and card.
 */
export async function pageMetadata(seo: PageSeo): Promise<Metadata> {
  const row = seo.page ? await getSeoSettings(seo.page) : null
  const title = row?.metaTitle?.trim() || seo.title
  const description = row?.metaDesc?.trim() || seo.description
  const canonical = absolute(row?.canonical?.trim() || seo.path)
  const custom = row?.ogImage?.trim() || seo.image?.trim()
  const image = custom ? { url: absolute(custom) } : { ...DEFAULT_OG_IMAGE, url: absolute(DEFAULT_OG_IMAGE.url) }

  return {
    title: { absolute: title },
    description,
    alternates: { canonical },
    openGraph: {
      type: seo.type ?? 'website',
      siteName: SITE_NAME,
      locale: 'en_UG',
      url: canonical,
      title,
      description,
      images: [{ ...image, alt: title }],
      ...(seo.type === 'article' && seo.article
        ? { ...seo.article, authors: [SITE_NAME] }
        : {}),
    },
    twitter: {
      card: 'summary_large_image',
      creator: '@bodo_desderio',
      title,
      description,
      images: [image.url],
    },
    ...(seo.noindex ? { robots: { index: false, follow: true } } : {}),
  }
}
